-- Intent rows for side-effecting tool calls (see the SQLite migration of the
-- same ordinal). A worker's PreToolUse hook writes one before the call runs and
-- its PostToolUse hook deletes it, so a surviving row marks a call a hard kill
-- may have cut mid-flight.
CREATE TABLE IF NOT EXISTS "tool_call_intents" (
  "id" text,
  "taskId" text NOT NULL,
  "agentId" text,
  "toolCallId" text NOT NULL,
  "toolName" text NOT NULL,
  "argsSummary" text,
  "createdAt" timestamptz(3) NOT NULL,
  "_rowid" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  PRIMARY KEY ("id"),
  UNIQUE ("taskId", "toolCallId")
);

CREATE UNIQUE INDEX "tool_call_intents__rowid_key" ON "tool_call_intents" ("_rowid");

ALTER TABLE "tool_call_intents" ADD FOREIGN KEY ("taskId") REFERENCES "agent_tasks" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;
